---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Toast: A background job in one toast, from start to finish.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change toast.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './toast.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="toast" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="tst dm">
  <div class="dm-main"><div class="tst-slot">
    <button type="button" class="pill line sm tst-make"><svg class="i s"><use href="#i-spark"/></svg><span>Make slides</span></button>
    <div class="tst-t" hidden>
      <div class="tst-hd">
        <span class="tst-dk idle" aria-hidden="true"><svg viewBox="0 0 64 40"></svg></span>
        <div class="tst-tx"><span class="tst-ti"></span><span class="tst-de"></span></div>
        <div class="tst-hb">
          <button type="button" class="ib tst-more" aria-expanded="false" aria-label="Show the steps" data-tip="Steps"><svg class="i s"><use href="#i-chev-d"/></svg></button>
          <button type="button" class="ib tst-stop" aria-label="Stop the job" data-tip="Stop"><svg class="i s"><use href="#i-stop"/></svg></button>
          <button type="button" class="ib tst-x" aria-label="Close" data-tip="Close" hidden><svg class="tst-ring" viewBox="0 0 28 28" aria-hidden="true" hidden><rect class="tst-tk" x=".75" y=".75" width="26.5" height="26.5"/><rect class="tst-rn" x=".75" y=".75" width="26.5" height="26.5" pathLength="100"/></svg><svg class="i s"><use href="#i-x"/></svg></button>
        </div>
      </div>
      <div class="fold shut tst-mf"><div><ol class="tst-st" aria-label="Steps"></ol></div></div>
      <div class="fold shut tst-ft"><div><div class="tst-fi"></div></div></div>
    </div>
    <div class="tst-sr" role="status" aria-live="polite"></div>
    <div class="tst-sr" role="alert" aria-live="assertive"></div>
  </div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './toast.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Toast ---------- */
/* the Job toast (owner, 26 Nov, from the toast lab's 2a): a job the agent runs in the background lives in one toast from start
   to finish. Its glyph is the news (a hand of slides, dealt as each one is drafted), its states change in place (working, a
   problem with its fix, done), its steps open inside it, and Close drains a visible countdown. Plain toasts (a success or an
   error with one action) are the same card: a status mark where the glyph goes, the words, Close, and the action in the
   footer. It grows out of the button that started it, sits where its host puts it (centred in the stage here) and moves
   with the library's own motion */
.tst{position:relative}
/* the toast on its way out and the one coming in share one cell, so each keeps its full width while they cross; the cell is
   as tall as its toast and keeps no room when there is none */
.tst-slot{position:relative;width:100%;display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:center}
.tst-slot>:is(.tst-t,.tst-make){grid-area:1/1}
/* the button that starts the job sits where its toast will: the toast grows out of it and, once closed, goes back into it */
.tst-make.under{visibility:hidden}
/* the card: up to 380px, the full width less its host's 16px gutters on a phone. Hover fills are a quiet 5% of the text
   colour so they show on the white card. Its hairlines are 10% of the text colour, as the lab set them: half of --dm-line doesn't
   show on Blueprint's dark raised grey */
.tst-t{width:100%;max-width:380px;box-sizing:border-box;background:var(--dm-raised);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow-pop);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent);--dm-tst-div:color-mix(in srgb,var(--dm-fg) 10%,transparent);overflow:clip;position:relative;touch-action:pan-y;user-select:none;-webkit-user-select:none}
.tst-t[hidden]{display:none}
/* (it grows with what it holds, grow(); its corners clip what is inside them exactly). The card's own height carries the motion,
   so its steps and its footer open and shut at once and only fade: two eased heights on top of each other would leave the
   card's edge trailing behind them */
.tst-t.growing{overflow-clip-margin:0px}
.tst-t .fold{transition:opacity var(--dm-t-fast) var(--dm-ease)}
.tst-t .fold.shut{transition:opacity var(--dm-t-fast) var(--dm-ease),visibility 0s var(--dm-t-fast)}
/* the head: the glyph, the words, then the toast's own buttons, all on one centre line, 16px in from every edge */
.tst-hd{display:flex;align-items:center;gap:var(--dm-s-3);padding:var(--dm-s-4)}
.tst-tx{flex:1;min-width:0}
.tst-ti{display:block;width:fit-content;max-width:100%;font-size:13px;font-weight:500;line-height:18px}
/* the line under the title wraps on a narrow toast rather than cutting off its news ("The sheet says 41k, not 14k") */
.tst-de{display:block;font-size:12px;line-height:18px;color:var(--dm-muted);font-variant-numeric:tabular-nums}
/* its icon buttons fill on hover, so they are measured by their box (ui-qa-gate, "boxes that fill"): Close's box, and the
   countdown ring drawn on it, end on the content's right edge, 16px in, where the footer's buttons end */
.tst-hb{display:flex;align-items:center;gap:var(--dm-s-1);flex:none}
.tst-hb .ib{width:28px;height:28px;position:relative}
.tst-hb .ib[hidden]{display:none}
.tst-more .i{transition:transform var(--dm-t) var(--dm-ease)}
.tst-more[aria-expanded="true"] .i{transform:rotate(180deg)}
/* a plain toast's status mark sits where the glyph goes: the vivid green tick, the red alert, the warning sign in the bright
   orange (its words stay in the text colour and its fix is .pill.warn, as the warning notices have them), a grey info mark or a spinner,
   with no disc behind it, so a toast carries two hues at most */
.tst-g{flex:none;width:20px;height:20px;display:grid;place-items:center;color:var(--dm-fg2)}
.tst-g .i{width:20px;height:20px}
.tst-g .spin{width:14px;height:14px;color:var(--dm-accent-mark)}
.tst-g[data-s="success"]{color:var(--dm-ok-mark)}
.tst-g[data-s="error"]{color:var(--dm-bad-mark)}
.tst-g[data-s="warning"]{color:var(--dm-warn-mark)}
.tst-g[data-s="stopped"]{color:var(--dm-muted)}
/* the countdown you can see: a ring round Close that drains; the pointer or the focus on the toast holds it */
.tst-ring{position:absolute;inset:0;width:28px;height:28px;pointer-events:none;fill:none}
.tst-ring rect{rx:13.25px;ry:13.25px;stroke-width:1.5}
:root:not([data-style="soft"],[data-style="clean"]) .tst-ring rect:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){rx:0;ry:0}
.tst-ring .tst-tk{stroke:color-mix(in srgb,var(--dm-line) 70%,transparent)}
.tst-ring .tst-rn{stroke:var(--dm-muted);stroke-dasharray:100 100;stroke-linecap:round}
.tst-ring[hidden]{display:none}
/* the steps, opened from the chevron, under a hairline: each step's mark sits centred in the glyph's column and its words
   start where the title's words do; a step's count is the same size as its words, so the two share a baseline */
/* (12px round the 28px rows puts the first and last step's words 16px and more from the hairline and the card's edge) */
.tst-st{list-style:none;margin:0;padding:var(--dm-s-3) 0;border-top:1px solid var(--dm-tst-div)}
.tst-st li{display:grid;grid-template-columns:var(--dm-tst-gw,64px) minmax(0,1fr) auto;column-gap:var(--dm-s-3);align-items:center;height:28px;padding:0 var(--dm-s-4);font-size:12.5px;line-height:18px;color:var(--dm-fg2)}
.tst-st .tst-lb{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tst-st .tst-mk{justify-self:center;width:16px;height:16px;display:grid;place-items:center}
.tst-st .tst-mk .i{width:16px;height:16px}
.tst-st .tst-mk .spin{width:12px;height:12px}
.tst-st .tst-vl{color:var(--dm-muted);font-variant-numeric:tabular-nums;white-space:nowrap}
.tst-st li[data-s="done"] .tst-mk{color:var(--dm-ok-mark)}
.tst-st li[data-s="done"] .tst-mk .i{stroke-width:2}
.tst-st li[data-s="now"]{color:var(--dm-fg)}
.tst-st li[data-s="now"] .tst-mk{color:var(--dm-accent-mark)}
.tst-st li[data-s="bad"]{color:var(--dm-fg)}
.tst-st li[data-s="bad"] .tst-mk{color:var(--dm-bad-mark)}
.tst-st li[data-s="paused"] .tst-mk{color:var(--dm-muted)}
.tst-st li[data-s="wait"]{color:var(--dm-muted)}
.tst-st .tst-pend{width:8px;height:8px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--dm-line-strong)}
/* the footer: the actions under a hairline, on the right, 16px from the hairline, the card's bottom and its side */
.tst-fi{display:flex;align-items:center;justify-content:flex-end;gap:var(--dm-s-2);padding:var(--dm-s-4);border-top:1px solid var(--dm-tst-div)}
.tst-fi .pill{min-width:0}
.tst-fi .pill.in{animation:tstbtn var(--dm-t) var(--dm-ease) backwards}
@keyframes tstbtn{from{opacity:0;transform:translateY(4px)}}
/* the box the toast grows out of: the button that started it, easing to where the toast sits and opening into it */
.tst-fly{position:absolute;z-index:3;background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);pointer-events:none}
.tst-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap}
.tst-make .i{width:14px;height:14px}
/* coming in without a button to grow from, and going: the library's own entrance for each style */
.tst-in{animation:tstin var(--dm-t-slow) var(--dm-ease) backwards}
@keyframes tstin{from{opacity:0;transform:translateY(14px) scale(.97);filter:blur(5px)}}
.tst-out{animation:tstout var(--dm-t) var(--dm-ease) both;pointer-events:none}
@keyframes tstout{to{opacity:0;transform:translateY(8px) scale(.98);filter:blur(4px)}}

/* the glyph: a hand of slides, dealt as each one is drafted */
.tst-dk{flex:none;width:64px;height:40px;display:block}
.tst-dk svg{width:64px;height:40px;display:block;overflow:visible}
/* the notes being read: a page with a line sweeping down it */
.tst-dk .tst-pg{transform-box:view-box;transform-origin:32px 24px;transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease)}
.tst-dk .tst-pp{fill:var(--dm-raised);stroke:var(--dm-muted);stroke-width:1.2}
.tst-dk .tst-pl{stroke:var(--dm-faint);stroke-width:1.4;stroke-linecap:round}
.tst-dk .tst-sc{stroke:var(--dm-accent-mark);stroke-width:1.6;stroke-linecap:round;opacity:0}
.tst-dk.read .tst-sc{opacity:1;animation:tstscan 1s var(--dm-ease-io) infinite alternate}
@keyframes tstscan{to{transform:translateY(13px)}}
.tst-dk:not(.read,.idle,.gone) .tst-pg{opacity:0;transform:scale(.6) translateY(10px)}
/* the cards: an outline of dashed slots once the deck is planned; each slide dealt into its slot as it is drafted, the one being
   drafted in the accent and in front; red where the check stopped */
.tst-dk .tst-cd{transform-box:view-box;transform-origin:32px 56px;transform:scale(.7);opacity:0;transition:transform var(--dm-t) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
.tst-dk .tst-cd .tst-b{fill:var(--dm-raised);stroke:var(--dm-faint);stroke-width:1.2;transition:fill var(--dm-t-fast) var(--dm-ease),stroke var(--dm-t-fast) var(--dm-ease)}
.tst-dk .tst-cd .tst-l{fill:none;stroke:var(--dm-faint);stroke-width:1.3;stroke-linecap:round;stroke-dasharray:8 8;stroke-dashoffset:8;transition:stroke-dashoffset var(--dm-t) var(--dm-ease),stroke var(--dm-t-fast) var(--dm-ease)}
:root:not([data-style="soft"],[data-style="clean"]) .tst-dk :is(.tst-cd .tst-b,.tst-pp):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){rx:0}
.tst-dk .tst-gh .tst-b{stroke:color-mix(in srgb,var(--dm-muted) 38%,var(--dm-raised));stroke-dasharray:2 1.6}
.tst-dk .tst-gh .tst-l{display:none}
.tst-dk.plan .tst-gh{opacity:1;transform:rotate(var(--dm-a));transition-delay:calc(var(--dm-i) * 36ms)}
.tst-dk .tst-cd:is(.made,.now,.chk,.bad){opacity:1;transform:rotate(var(--dm-a))}
.tst-dk .tst-cd.made .tst-b{stroke:var(--dm-fg2)}
.tst-dk .tst-cd.made .tst-l{stroke-dashoffset:0;stroke:color-mix(in srgb,var(--dm-muted) 70%,var(--dm-raised))}
.tst-dk .tst-cd.now{transform:rotate(var(--dm-a)) translateY(-3px)}
.tst-dk .tst-cd:is(.now,.chk) .tst-b{stroke:var(--dm-accent-mark);fill:color-mix(in srgb,var(--dm-accent-mark) 10%,var(--dm-raised))}
.tst-dk .tst-cd.now .tst-b{stroke-width:1.5}
.tst-dk .tst-cd.now .tst-l{stroke:var(--dm-accent-mark);stroke-dashoffset:0}
.tst-dk .tst-cd.chk{transform:rotate(var(--dm-a)) translateY(-2px)}
.tst-dk .tst-cd.bad{transform:rotate(var(--dm-a)) translateY(-4px)}
.tst-dk .tst-cd.bad .tst-b{fill:var(--dm-bad-mark);stroke:var(--dm-bad-mark)}
.tst-dk .tst-cd.bad .tst-l{stroke:#fff;stroke-dashoffset:0}
/* done: the hand closes into a neat deck and the green tick lands in front of it */
.tst-dk.done .tst-gh{opacity:0;transition-delay:0s}
.tst-dk.done .tst-cd:not(.tst-gh){transform:rotate(calc(var(--dm-a) * .16)) translateY(3px)}
.tst-dk .tst-ok{transform-box:fill-box;transform-origin:center;transform:scale(0);opacity:0;transition:transform var(--dm-t) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
.tst-dk .tst-ok circle{fill:var(--dm-ok-mark);stroke:var(--dm-raised);stroke-width:2}
.tst-dk .tst-ok path{fill:none;stroke:#fff;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.tst-dk.done .tst-ok{transform:none;opacity:1;transition-delay:.2s}
/* gone (undone or discarded): the cards fold back to where they came from, and the notes they were made from are back */
.tst-dk.gone .tst-cd{opacity:0;transform:scale(.6);transition-delay:0s}
/* reduced motion: things only fade; moves and turns happen at once */
@media (prefers-reduced-motion:reduce){
  .tst-dk *,.tst-more .i{transition-property:opacity!important;transition-delay:0s!important}
  .tst-dk .tst-sc{animation:none}
}
@keyframes tstfade{from{opacity:0}}
@keyframes tstfadeo{to{opacity:0}}

/* Clean: the card's ordinary round corners (16px), the footer an off-white strip with its buttons 16px from its hairline, the
   card's bottom and its side; the ink primary and the flat secondary are Clean's own. It rises 8px from .98 and leaves with a
   fade, with no blur */
:root[data-style="clean"] .tst-t,:root [data-style="clean"] .tst-t,:root [data-style="clean"].tst-t{border-radius:calc(12px * var(--dm-rk-l,var(--dm-rk)))}
:root[data-style="clean"] .tst-st,:root [data-style="clean"] .tst-st,:root [data-style="clean"].tst-st{border-top-color:var(--dm-line)}
:root[data-style="clean"] .tst-fi,:root [data-style="clean"] .tst-fi,:root [data-style="clean"].tst-fi{padding:var(--dm-strip-y) var(--dm-s-4);background:var(--dm-strip);border-top-color:var(--dm-line)}
:root[data-style="clean"] .tst-in,:root [data-style="clean"] .tst-in,:root [data-style="clean"].tst-in{animation-name:clcard}
@keyframes tstoutc{to{opacity:0;transform:translateY(6px) scale(.98)}}
:root[data-style="clean"] .tst-out,:root [data-style="clean"] .tst-out,:root [data-style="clean"].tst-out{animation-name:tstoutc;animation-duration:var(--dm-t-fast)}
/* Blueprint wipes in and goes in a short hard beat */
@keyframes tstinb{from{opacity:0;clip-path:inset(0 0 100% 0)}35%{opacity:1}to{clip-path:inset(0 0 0 0)}}
:root:not([data-style="soft"],[data-style="clean"]) .tst-in:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation-name:tstinb}
@keyframes tstoutb{to{opacity:0;transform:translateY(4px)}}
:root:not([data-style="soft"],[data-style="clean"]) .tst-out:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation-name:tstoutb;animation-duration:var(--dm-t-fast)}
/* reduced motion: it only fades in and out, in every style (after the styles' own, which it outranks or ties) */
@media (prefers-reduced-motion:reduce){.tst-slot .tst-t.tst-in,.tst-fi .pill.in{animation-name:tstfade}.tst-slot .tst-t.tst-out{animation-name:tstfadeo}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, REVEAL, grow, swap } from '../core/core.js';
// the Job toast (owner, 26 Nov): a job the agent runs in the background ("Make slides" from the notes) lives in one toast from
// start to finish. It is an agent at work, so its demo keeps playing under a resting pointer (DM.PLAYS); its timing goes
// through the controller (c.later), and what the visitor sets off keeps running once they take over
DM.def('toast', (r, c) => {
  const q = s => $(s, r);
  const make = q('.tst-make'), slot = q('.tst-slot'), T = q('.tst-t'), G = q('.tst-dk'), svg = q('.tst-dk svg'), tx = q('.tst-tx'), hb = q('.tst-hb');
  const ti = q('.tst-ti'), de = q('.tst-de'), moreB = q('.tst-more'), stopB = q('.tst-stop'), xB = q('.tst-x'), ring = q('.tst-ring'), rn = q('.tst-ring .tst-rn');
  const more = q('.tst-mf'), steps = q('.tst-st'), ft = q('.tst-ft'), ftIn = q('.tst-fi');
  const [polite, loud] = $$('.tst-sr', r);
  // the job's own clock: with reduced motion it still takes its time (a few hundred ms a step), so each state can be read
  const wait = ms => new Promise(res => c.later(REDUCE ? Math.min(ms, 400) : ms, res));
  const motion = () => { const cs = getComputedStyle(r), s = v => parseFloat(cs.getPropertyValue(v)) * 1000 || 340; return { ease:cs.getPropertyValue('--dm-ease').trim() || 'ease', t:s('--dm-t'), fast:s('--dm-t-fast'), slow:s('--dm-t-slow'), m:REVEAL[cs.getPropertyValue('--dm-motion').trim()] || REVEAL.soft }; };
  const N = 12, SEC = ['Cover', 'Agenda', 'Revenue', 'North', 'South', 'Plan vs actual', 'By region', 'Hiring', 'Open roles', 'Risks', 'Data move', 'Next steps'];

  /* the glyph: a page for the notes, twelve dashed slots fanned round a point under it, twelve cards, and the tick */
  const ang = i => -32 + i * 64 / (N - 1);
  const card = (i, k) => `<g class="tst-cd${k}" style="--dm-a:${ang(i).toFixed(2)}deg;--dm-i:${i}"><rect class="tst-b" x="26" y="6" width="12" height="20" rx="2"/><path class="tst-l" d="M28.5 10h6M28.5 13.5h7M28.5 17h4.5" pathLength="8"/></g>`;
  svg.innerHTML = '<g class="tst-pg"><rect class="tst-pp" x="23.5" y="6.5" width="17" height="22" rx="2.5"/><path class="tst-pl" d="M27 12h10M27 15.5h8M27 19h10M27 22.5h6"/><path class="tst-sc" d="M25.5 10h13"/></g>'
    + '<g>' + Array.from({ length:N }, (_, i) => card(i, ' tst-gh')).join('') + '</g><g class="tst-fan">' + Array.from({ length:N }, (_, i) => card(i, '')).join('') + '</g>'
    + '<g class="tst-ok"><circle cx="41" cy="27" r="6.5"/><path d="M38.3 27.1l1.9 1.9 3.5-3.6"/></g>';
  const fan = $('.tst-fan', svg), cards = $$('.tst-fan .tst-cd', svg);
  // the card eases to its new height as its words wrap or its steps and footer come and go (grow(), centred in the stage)
  c.offs.push(grow(T));
  const fitNow = () => { T.style.transition = 'none'; T.style.height = T.firstElementChild.offsetHeight + 'px'; void T.offsetHeight; T.style.transition = ''; };
  // the card being drafted, or the one the check stopped on, comes to the front of the hand; the hand goes back in order after
  const order = () => cards.forEach(e => fan.appendChild(e));
  const glyph = k => { G.classList.remove('idle', 'read', 'plan', 'done', 'gone'); k.split(' ').filter(Boolean).forEach(x => G.classList.add(x)); };
  const cardAs = (i, k) => { const e = cards[i]; e.classList.remove('made', 'now', 'chk', 'bad'); if (k) e.classList.add(k);
    if (k === 'now' || k === 'bad') fan.appendChild(e); else if (k === 'made' && fan.lastElementChild === e) order(); };

  /* the steps, opened from the chevron; a step's mark sits in the glyph's column */
  const STEPS = ['Read the notes', 'Outline 12 slides', 'Draft the slides', 'Check the numbers'];
  steps.innerHTML = STEPS.map(s => `<li data-s="wait"><span class="tst-mk"><span class="tst-pend"></span></span><span class="tst-lb">${s}</span><span class="tst-vl"></span></li>`).join('');
  const rows = [...steps.children];
  const MK = { done:I('check'), now:'<span class="spin"></span>', bad:I('alert'), paused:I('pause'), wait:'<span class="tst-pend"></span>' };
  const stepAs = (i, s, v = '') => { const e = rows[i]; if (e.dataset.s !== s){ e.dataset.s = s; $('.tst-mk', e).innerHTML = MK[s]; } $('.tst-vl', e).textContent = v; };

  const S = { phase:'idle', n:0, tok:0, fixed:false, skipped:false, at:'read' };

  /* words that change cross-fade (swap); the words that say what is running sweep (.shim); a counter ticks over at once */
  const sayTi = (text, shim) => { if (ti.textContent === text && !ti._sw){ ti.classList.toggle('shim', !!shim); return; } swap(ti, text); c.later(REDUCE ? 0 : 170, () => ti.classList.toggle('shim', !!shim)); };
  const sayDe = (text, now) => { if (now){ if (de._sw){ clearTimeout(de._sw.t); de._sw = null; de.classList.remove('out'); } de.textContent = text; } else swap(de, text); };
  // announcements: progress politely, a problem at once
  const tell = (text, now) => { const el = now ? loud : polite; el.textContent = ''; c.later(60, () => { el.textContent = text; }); };

  /* the countdown on Close: a ring that drains; the pointer or the focus on the toast holds it, and it closes the toast */
  let cd = null;
  const held = () => T.matches(':hover') || T.contains(document.activeElement);
  const countdown = ms => { if (cd){ cd.cancel(); cd = null; } ring.toggleAttribute('hidden', !ms); if (!ms) return;
    cd = rn.animate([{ strokeDashoffset:0 }, { strokeDashoffset:100 }], { duration:ms, fill:'forwards', easing:'linear' });
    if (held()) cd.pause();
    cd.onfinish = () => { cd = null; dismiss(); }; };
  const holdT = () => { if (cd && cd.playState === 'running') cd.pause(); };
  const goT = () => { if (cd && cd.playState === 'paused' && !held()) cd.play(); };
  c.on(T, 'pointerenter', holdT); c.on(T, 'pointerleave', goT); c.on(T, 'focusin', holdT); c.on(T, 'focusout', () => c.later(0, goT));
  c.offs.push(() => { if (cd) cd.cancel(); });

  /* the footer's buttons for each state: the secondary white and outlined, the one that moves the job on the primary */
  const foot = acts => {
    if (!acts){ ft.classList.add('shut'); return; }
    const was = !ft.classList.contains('shut');
    ftIn.innerHTML = acts.map(([k, t]) => `<button type="button" class="pill sm ${k}${was ? ' in' : ''}">${t}</button>`).join('');
    [...ftIn.children].forEach((b, i) => b.addEventListener('click', acts[i][2]));
    ft.classList.remove('shut');
  };
  const btnOf = t => [...ftIn.querySelectorAll('button')].find(b => b.textContent === t);

  const P = {
    read:    { ti:'Reading your notes…', de:'3 sections · 212 words', work:1 },
    outline: { ti:'Outlining the deck…', de:'12 slides planned', work:1 },
    draft:   { ti:'Drafting slides…', de:() => `Slide ${Math.min(S.n + 1, N)} of 12 · ${SEC[Math.min(S.n, N - 1)]}`, work:1 },
    check:   { ti:'Checking the numbers…', de:'Against the Q3 sheet', work:1 },
    error:   { ti:'Slide 7 doesn’t match', de:'The sheet says 41k, not 14k', acts:[['line', 'Skip', () => skip()], ['primary', 'Fix slide 7', () => fix()]] },
    fix:     { ti:'Fixing slide 7…', de:'Using 41k from the sheet', work:1 },
    done:    { ti:'12 slides ready', de:() => S.skipped ? 'Q3 planning deck · 1 to check' : 'Q3 planning deck · 1 fixed', acts:[['line', 'Undo', () => undo()], ['primary', 'Open', () => openDeck()]], time:10000 },
    stopped: { ti:() => S.at === 'draft' ? `Stopped at slide ${S.n}` : S.at === 'check' ? 'Stopped while checking' : 'Stopped before drafting', de:() => `${S.n} of 12 drafted · nothing lost`, acts:[['line', 'Discard', () => discard()], ['primary', 'Resume', () => resume()]] },
    removed: { ti:'Deck removed', de:'Your notes are unchanged', acts:[['line', 'Redo', () => redo()]], time:6000 }
  };
  const val = v => typeof v === 'function' ? v() : v;
  const setPhase = p => {
    S.phase = p; const d = P[p];
    sayTi(val(d.ti), d.work); sayDe(val(d.de));
    stopB.hidden = !d.work; xB.hidden = !!d.work; moreB.hidden = p === 'removed';
    if (p === 'removed') toggleMore(false);
    foot(d.acts); countdown(d.time || 0);
    // the steps follow the job
    const sv = { read:['now', 'wait', 'wait', 'wait'], outline:['done', 'now', 'wait', 'wait'], draft:['done', 'done', 'now', 'wait'], check:['done', 'done', 'done', 'now'], error:['done', 'done', 'done', 'bad'], fix:['done', 'done', 'done', 'now'], done:['done', 'done', 'done', 'done'], removed:['done', 'done', 'done', 'done'] }[p];
    if (sv) sv.forEach((s, i) => stepAs(i, s, i === 2 && s === 'now' ? `${S.n} of 12` : i === 3 && (p === 'error' || p === 'fix') ? 'Slide 7' : ''));
    if (p === 'stopped'){ const at = ['read', 'outline', 'draft', 'check'].indexOf(S.at); rows.forEach((e, i) => stepAs(i, i < at ? 'done' : i === at ? 'paused' : 'wait', i === at && i === 2 ? `${S.n} of 12` : '')); }
  };

  /* it comes in: it grows out of the button that started it, in the same place, and its parts follow one after another; it
     goes back into the button when it is closed. Both ease with the style's own motion; with reduced motion they only fade */
  const box = el => { const sb = slot.getBoundingClientRect(), b = el.getBoundingClientRect();
    return { left:b.left - sb.left + 'px', top:b.top - sb.top + 'px', width:b.width + 'px', height:b.height + 'px', borderRadius:getComputedStyle(el).borderTopLeftRadius }; };
  const flyer = from => { const f = document.createElement('div'); f.className = 'tst-fly'; Object.assign(f.style, from); slot.appendChild(f); c.offs.push(() => f.remove()); return f; };
  const show = () => {
    T.getAnimations().forEach(a => a.cancel()); T.classList.remove('tst-out');
    const M = motion(), from = box(make);
    T.hidden = false; T.style.opacity = ''; make.classList.add('under'); fitNow();
    if (REDUCE){ T.animate([{ opacity:0 }, { opacity:1 }], { duration:M.fast }); return; }
    const to = box(T), fly = flyer(from); T.style.opacity = '0';
    const a = fly.animate([from, to], { duration:M.slow, easing:M.ease, fill:'forwards' });
    a.finished.then(() => {
      T.style.opacity = ''; fly.animate([{ opacity:1 }, { opacity:0 }], { duration:M.fast, fill:'forwards' }).finished.then(() => fly.remove(), () => fly.remove());
      [G, tx, hb].forEach((el, i) => { const [k] = M.m.part, { transform, ...look } = k;
        if (Object.keys(look).length) el.animate([{ offset:0, ...look }, {}], { duration:M.m.partMs, delay:i * M.m.step, easing:M.m.ease, fill:'backwards' });
        if (transform) el.animate([{ transform }, { transform:'none' }], { duration:M.m.partMs, delay:i * M.m.step, easing:M.m.ease, fill:'backwards' }); });
    }, () => fly.remove());
  };
  // the button comes back where the toast was
  const back = () => { make.classList.remove('under'); if (!REDUCE) make.animate([{ opacity:0, transform:'scale(.96)' }, { opacity:1, transform:'none' }], { duration:motion().t, easing:motion().ease }); };
  const exit = () => new Promise(res => {
    if (T.hidden){ res(); return; }
    const M = motion(), done = () => { T.hidden = true; T.style.transform = ''; T.style.opacity = ''; T.getAnimations().forEach(a => a.cancel()); back(); res(); };
    if (REDUCE){ T.animate([{ opacity:1 }, { opacity:0 }], { duration:M.fast, fill:'forwards' }); c.later(M.fast, done); return; }
    // its words fade at once, and the card eases back into the button
    const from = box(T); make.classList.remove('under'); const to = box(make); make.classList.add('under');
    const fly = flyer(from); T.animate([{ opacity:1 }, { opacity:0 }], { duration:M.fast * .6, fill:'forwards' });
    const a = fly.animate([from, to], { duration:M.t, easing:M.ease, fill:'forwards' });
    a.finished.then(() => { done(); fly.animate([{ opacity:1 }, { opacity:0 }], { duration:M.fast, fill:'forwards' }).finished.then(() => fly.remove(), () => fly.remove()); }, () => { fly.remove(); done(); });
  });
  const label = t => { make.querySelector('span').textContent = t; };
  /* Close, Escape or a swipe: a finished toast goes; a job still running carries on, and the button brings its toast back */
  const after = () => {
    if (P[S.phase] && P[S.phase].work) label('Show progress');
    else if (S.phase === 'stopped' || S.phase === 'error') label('Show job');
    else { S.phase = 'idle'; label('Make slides'); }
  };
  const dismiss = () => { if (T.hidden || closing) return; countdown(0); closing = true; after(); exit().then(() => { closing = false; }); };
  let closing = false;
  const toggleMore = open => { open = open ?? more.classList.contains('shut'); more.classList.toggle('shut', !open); moreB.setAttribute('aria-expanded', open); moreB.setAttribute('aria-label', open ? 'Hide the steps' : 'Show the steps'); moreB.dataset.tip = open ? 'Hide steps' : 'Steps'; };

  /* the job */
  const reset = () => { S.n = 0; S.fixed = false; S.skipped = false; cards.forEach((e, i) => cardAs(i)); order(); glyph('idle'); rows.forEach((e, i) => stepAs(i, 'wait')); toggleMore(false); };
  const start = () => {
    // a job whose toast was dismissed: the button brings its toast back
    if (!T.hidden || closing) return;
    // a job whose toast was closed before it finished, or that finished while it was closed: the button brings it back
    if (P[S.phase]){ label('Make slides'); show(); if (S.phase === 'done') countdown(P.done.time); return; }
    reset(); S.tok++; const tok = S.tok;
    label('Make slides'); setPhase('read'); glyph('read');
    show(); run(tok, 'read');
    tell('Making slides from your notes');
  };
  const live = tok => tok === S.tok && !c.dead;
  async function run(tok, from){
    if (from === 'read'){ S.at = 'read'; setPhase('read'); glyph('read'); await wait(1700); if (!live(tok)) return; from = 'outline'; }
    if (from === 'outline'){ S.at = 'outline'; setPhase('outline'); glyph('plan'); await wait(1300); if (!live(tok)) return; from = 'draft'; }
    if (from === 'draft'){
      S.at = 'draft'; setPhase('draft'); glyph('plan');
      while (S.n < N){
        const i = S.n; cardAs(i, 'now'); sayDe(val(P.draft.de), i > 0); stepAs(2, 'now', `${i + 1} of 12`);
        await wait(400); if (!live(tok)) return;
        cardAs(i, 'made'); S.n++;
        if (S.n === 6) tell('Half the slides are drafted');
      }
      from = 'check';
    }
    if (from === 'check' || from === 'recheck'){
      S.at = 'check'; setPhase('check'); glyph('plan');
      for (let i = from === 'recheck' ? 7 : 0; i < N; i++){
        if (i === 6 && !S.fixed && !S.skipped){ cardAs(i, 'bad'); setPhase('error'); tell('Slide 7 doesn’t match the sheet. Fix slide 7 or skip it.', true); return; }
        if (S.skipped && i === 6) continue;
        cardAs(i, 'chk'); await wait(120); if (!live(tok)) return; cardAs(i, 'made');
      }
    }
    cards.forEach((e, i) => { if (!(S.skipped && i === 6)) cardAs(i, 'made'); });
    await wait(150); if (!live(tok)) return;
    setPhase('done'); glyph('done'); if (T.hidden) label('Show job');
    tell('12 slides ready. Open the deck or undo it.');
  }
  const fix = async () => { S.tok++; const tok = S.tok; setPhase('fix'); cardAs(6, 'now'); tell('Fixing slide 7');
    await wait(1500); if (!live(tok)) return; S.fixed = true; cardAs(6, 'made'); run(tok, 'recheck'); };
  const skip = () => { S.skipped = true; S.tok++; run(S.tok, 'recheck'); };
  const stop = () => { if (!P[S.phase] || !P[S.phase].work) return; S.tok++;
    // stopping a fix goes back to the problem it was fixing
    if (S.phase === 'fix'){ cardAs(6, 'bad'); setPhase('error'); return; }
    cards.forEach((e, i) => { if (e.classList.contains('now') || e.classList.contains('chk')) cardAs(i, i < S.n ? 'made' : ''); });
    if (G.classList.contains('read')) glyph('idle');
    setPhase('stopped'); tell(`Stopped. ${S.n} of 12 drafted. Resume or discard.`); };
  const resume = () => { S.tok++; run(S.tok, S.at); };
  const discard = async () => { S.tok++; countdown(0); glyph('gone'); tell('Job discarded'); S.phase = 'idle'; label('Make slides'); await exit(); reset(); };
  const undo = () => { setPhase('removed'); glyph('gone'); tell('Deck removed. Your notes are unchanged.'); };
  const redo = () => { cards.forEach((e, i) => { if (!(S.skipped && i === 6)) cardAs(i, 'made'); }); glyph('done'); setPhase('done'); tell('Deck restored'); };
  const openDeck = async () => { countdown(0); tell('Opening the deck'); S.phase = 'idle'; label('Make slides'); await exit(); };

  c.on(make, 'click', start);
  c.on(moreB, 'click', () => toggleMore());
  c.on(stopB, 'click', stop);
  c.on(xB, 'click', dismiss);
  // Escape closes the toast while the focus is in it, and the focus goes back to the button that started it
  c.on(T, 'keydown', e => { if (e.key !== 'Escape' || T.hidden) return; const f = T.contains(document.activeElement); dismiss(); if (f) c.later(motion().t + 20, () => make.focus({ preventScroll:true })); });

  /* swipe it away: it follows the finger or the pointer sideways and goes once it has moved far enough, or eases back */
  let sw = null;
  c.on(T, 'pointerdown', e => { if (e.button || e.target.closest('button')) return; sw = { x:e.clientX, y:e.clientY, t:performance.now(), dx:0, id:e.pointerId, on:false }; });
  c.on(T, 'pointermove', e => { if (!sw || e.pointerId !== sw.id) return; const dx = e.clientX - sw.x, dy = e.clientY - sw.y;
    if (!sw.on){ if (Math.abs(dx) < 6 || Math.abs(dy) > Math.abs(dx)) return; sw.on = true; T.setPointerCapture(e.pointerId); }
    sw.dx = dx; T.style.transform = `translateX(${dx}px)`; T.style.opacity = String(Math.max(.2, 1 - Math.abs(dx) / 260)); });
  const swEnd = e => { if (!sw || e.pointerId !== sw.id) return; const s = sw; sw = null; if (!s.on) return;
    const v = Math.abs(s.dx) / Math.max(1, performance.now() - s.t), M = motion();
    if (Math.abs(s.dx) > 90 || v > .6){ const dir = Math.sign(s.dx) || 1; countdown(0);
      const a = T.animate([{ transform:`translateX(${s.dx}px)`, opacity:T.style.opacity }, { transform:`translateX(${dir * 420}px)`, opacity:0 }], { duration:M.t, easing:M.ease, fill:'forwards' });
      after(); a.finished.then(() => { T.hidden = true; a.cancel(); T.style.transform = ''; T.style.opacity = ''; back(); }, () => {}); }
    else { T.animate([{ transform:`translateX(${s.dx}px)`, opacity:T.style.opacity }, { transform:'none', opacity:1 }], { duration:M.t, easing:M.ease }); T.style.transform = ''; T.style.opacity = ''; } };
  c.on(T, 'pointerup', swEnd); c.on(T, 'pointercancel', swEnd);

  /* the demo: the person makes slides, opens the steps, fixes the problem the check finds, tries Undo and Redo, then opens
     the deck */
  c.story(async s => {
    await s.beat(2);
    await s.tap(make);
    await s.beat(5);
    await s.tap(moreB);
    s.away();
    await s.until(() => S.n >= 9);
    await s.tap(moreB);
    s.away();
    await s.until(() => S.phase === 'error');
    await s.beat(3);
    await s.tap(btnOf('Fix slide 7'));
    s.away();
    await s.until(() => S.phase === 'done');
    await s.beat(4);
    await s.tap(btnOf('Undo'));
    await s.beat(3);
    await s.tap(btnOf('Redo'));
    s.away();
    await s.beat(5);
    await s.tap(btnOf('Open'));
    s.away();
  });
});
